#[cfg(test)]mod tests{use super::*;#[test]fn additional_array_and_string_methods(){let mut r=Runtime::new();assert_eq!(r.execute("let a=[1,2,3];a.shift();a.unshift(8,9);a.slice(1,3).join(\"-\");").unwrap(),Value::String("9-2".into()));assert_eq!(r.execute("a.concat([4,5]).join(\"-\");").unwrap(),Value::String("8-9-2-3-4-5".into()));assert_eq!(r.execute("\"abcdef\".slice(1,4);").unwrap(),Value::String("bcd".into()));assert_eq!(r.execute("\"ha\".repeat(3);").unwrap(),Value::String("hahaha".into()));}#[test]fn expanded_math_and_number_helpers(){let mut r=Runtime::new();assert_eq!(r.execute("Math.sin(0);").unwrap(),Value::Number(0.0));assert_eq!(r.execute("Math.log10(100);").unwrap(),Value::Number(2.0));assert_eq!(r.execute("Number.isInteger(4);").unwrap(),Value::Boolean(true));assert_eq!(r.execute("Number.isInteger(4.5);").unwrap(),Value::Boolean(false));assert_eq!(r.execute("Number.isNaN(NaN);").unwrap_err().to_string().contains("NaN"),true);assert_eq!(r.execute("Array.isArray([1,2]);").unwrap(),Value::Boolean(true));assert_eq!(r.execute("Array.isArray({x:1});").unwrap(),Value::Boolean(false));let x=r.execute("Math.random();").unwrap();assert!(matches!(x,Value::Number(n) if n>=0.0&&n<1.0));}#[test]fn math_constants(){let mut r=Runtime::new();assert_eq!(r.execute("Math.PI;").unwrap(),Value::Number(std::f64::consts::PI));assert_eq!(r.execute("Math.E;").unwrap(),Value::Number(std::f64::consts::E));}#[test]fn switch_statements(){let mut r=Runtime::new();assert_eq!(r.execute("let x=2;let y=0;switch(x){case 1:y=10;break;case 2:y=20;case 3:y=y+1;break;default:y=99;}y;").unwrap(),Value::Number(21.0));assert_eq!(r.execute("let x=8;switch(x){case 1:1;break;default:7;}").unwrap(),Value::Number(7.0));}#[test]fn math_builtins(){let mut r=Runtime::new();assert_eq!(r.execute("Math.abs(-4);").unwrap(),Value::Number(4.0));assert_eq!(r.execute("Math.floor(3.9);").unwrap(),Value::Number(3.0));assert_eq!(r.execute("Math.ceil(3.1);").unwrap(),Value::Number(4.0));assert_eq!(r.execute("Math.sqrt(81);").unwrap(),Value::Number(9.0));assert_eq!(r.execute("Math.pow(2,5);").unwrap(),Value::Number(32.0));assert_eq!(r.execute("Math.max(1,7,3);").unwrap(),Value::Number(7.0));assert_eq!(r.execute("Math.min(1,7,3);").unwrap(),Value::Number(1.0));}#[test]fn string_character_and_replace_methods(){let mut r=Runtime::new();assert_eq!(r.execute("\"hello\".charAt(1);").unwrap(),Value::String("e".into()));assert_eq!(r.execute("\"hello\".replace(\"ll\",\"y\");").unwrap(),Value::String("heyo".into()));assert_eq!(r.execute("\"hello\".substring(1,4);").unwrap(),Value::String("ell".into()));assert_eq!(r.execute("\"hello\".charCodeAt(0);").unwrap(),Value::Number(104.0));}#[test]fn conversion_and_numeric_builtins(){let mut r=Runtime::new();assert_eq!(r.execute("Number(\"12\");").unwrap(),Value::Number(12.0));assert_eq!(r.execute("String(42);").unwrap(),Value::String("42".into()));assert_eq!(r.execute("Boolean(0);").unwrap(),Value::Boolean(false));assert_eq!(r.execute("parseInt(\"27px\");").unwrap(),Value::Number(27.0));assert_eq!(r.execute("parseFloat(\"3.5rem\");").unwrap(),Value::Number(3.5));assert_eq!(r.execute("isNaN(Number(\"no\"));").unwrap(),Value::Boolean(true));assert_eq!(r.execute("isFinite(10);").unwrap(),Value::Boolean(true));assert_eq!(r.execute("typeof missingVariable;").unwrap(),Value::String("undefined".into()));}#[test]fn delete_operator(){let mut r=Runtime::new();assert_eq!(r.execute("let o={x:1};delete o.x;").unwrap(),Value::Boolean(true));assert_eq!(r.execute("\"x\" in o;").unwrap(),Value::Boolean(false));assert_eq!(r.execute("let a=[1,2];delete a[0];").unwrap(),Value::Boolean(true));assert_eq!(r.execute("a.length;").unwrap(),Value::Number(2.0));assert_eq!(r.execute("a[0];").unwrap(),Value::Undefined);}#[test]fn in_operator(){let mut r=Runtime::new();assert_eq!(r.execute("\"x\" in {x:1};").unwrap(),Value::Boolean(true));assert_eq!(r.execute("\"y\" in {x:1};").unwrap(),Value::Boolean(false));assert_eq!(r.execute("0 in [4,5];").unwrap(),Value::Boolean(true));assert_eq!(r.execute("2 in [4,5];").unwrap(),Value::Boolean(false));assert_eq!(r.execute("\"length\" in [4];").unwrap(),Value::Boolean(true));assert!(r.execute("\"x\" in 3;").is_err());}#[test]fn nullish_coalescing(){let mut r=Runtime::new();assert_eq!(r.execute("null ?? 7;").unwrap(),Value::Number(7.0));assert_eq!(r.execute("undefined ?? 8;").unwrap(),Value::Number(8.0));assert_eq!(r.execute("0 ?? 9;").unwrap(),Value::Number(0.0));assert_eq!(r.execute("false ?? true;").unwrap(),Value::Boolean(false));assert_eq!(r.execute("let x=0;4 ?? (x=1);x;").unwrap(),Value::Number(0.0));}#[test]fn compound_property_assignments(){let mut r=Runtime::new();assert_eq!(r.execute("let o={x:2};o.x+=3;o.x*=4;o.x;").unwrap(),Value::Number(20.0));assert_eq!(r.execute("let a=[2];a[0]+=5;a[0];").unwrap(),Value::Number(7.0));}#[test]fn compound_assignments(){let mut r=Runtime::new();assert_eq!(r.execute("let x=10;x+=5;x-=2;x*=3;x/=2;x%=7;x;").unwrap(),Value::Number(5.5));let mut r=Runtime::new();assert_eq!(r.execute("let s=\"hi\";s+=\"!\";s;").unwrap(),Value::String("hi!".into()));}#[test]fn compound_assignment_const_is_error(){let mut r=Runtime::new();assert!(r.execute("const x=1;x+=1;").is_err());}#[test]fn increment_and_decrement(){let mut r=Runtime::new();assert_eq!(r.execute("let x=2; x++; ++x; x--; --x; x;").unwrap(),Value::Number(2.0));let mut r=Runtime::new();assert_eq!(r.execute("let x=3; x++;").unwrap(),Value::Number(3.0));assert_eq!(r.execute("let x=3; ++x;").unwrap(),Value::Number(4.0));}#[test]fn increment_string_uses_numeric_result(){let mut r=Runtime::new();assert_eq!(r.execute("let x=\"2\";x++;").unwrap(),Value::Number(2.0));assert_eq!(r.execute("x;").unwrap(),Value::Number(3.0));}#[test]fn increment_const_is_error(){let mut r=Runtime::new();assert!(r.execute("const x=1; x++;").is_err());}#[test]fn functions(){let mut r=Runtime::new();assert_eq!(r.execute("function add(a,b){return a+b;}add(2,5);").unwrap(),Value::Number(7.0))}#[test]fn arrays_and_mutation(){let mut r=Runtime::new();assert_eq!(r.execute("let a=[3,4];a[1]=9;a[0]+a[1];").unwrap(),Value::Number(12.0))}#[test]fn object_properties(){let mut r=Runtime::new();assert_eq!(r.execute("let o={x:4, name:'hi'};o.x=7;o.x;").unwrap(),Value::Number(7.0));assert_eq!(r.execute("o['name'];").unwrap(),Value::String("hi".into()))}#[test]fn array_length(){let mut r=Runtime::new();assert_eq!(r.execute("let a=[1,2,3];a.length;").unwrap(),Value::Number(3.0))}#[test]fn typeof_operator(){let mut r=Runtime::new();assert_eq!(r.execute("typeof 1;").unwrap(),Value::String("number".into()));assert_eq!(r.execute("typeof \"x\";").unwrap(),Value::String("string".into()));assert_eq!(r.execute("typeof true;").unwrap(),Value::String("boolean".into()));assert_eq!(r.execute("typeof undefined;").unwrap(),Value::String("undefined".into()));assert_eq!(r.execute("typeof null;").unwrap(),Value::String("object".into()));}#[test]fn void_operator(){let mut r=Runtime::new();assert_eq!(r.execute("void 123;").unwrap(),Value::Undefined);assert_eq!(r.execute("let x=0;void (x=5);x;").unwrap(),Value::Number(5.0));}#[test]fn conditional_operator(){let mut r=Runtime::new();assert_eq!(r.execute("true ? 4 : 9;").unwrap(),Value::Number(4.0));assert_eq!(r.execute("false ? 4 : 9;").unwrap(),Value::Number(9.0));assert_eq!(r.execute("let x=0;true ? 7 : (x=1);x;").unwrap(),Value::Number(0.0));}#[test]fn array_methods(){let mut r=Runtime::new();assert_eq!(r.execute("let a=[1];a.push(2);a.length;").unwrap(),Value::Number(2.0));assert_eq!(r.execute("a.includes(2);").unwrap(),Value::Boolean(true));assert_eq!(r.execute("a.indexOf(2);").unwrap(),Value::Number(1.0));assert_eq!(r.execute("a.pop();").unwrap(),Value::Number(2.0));assert_eq!(r.execute("a.length;").unwrap(),Value::Number(1.0));}#[test]fn string_methods(){let mut r=Runtime::new();assert_eq!(r.execute('"abc".toUpperCase();').unwrap(),Value::String("ABC".into()));assert_eq!(r.execute('"abc".includes("b");').unwrap(),Value::Boolean(true));}#[test]fn additional_array_methods(){let mut r=Runtime::new();assert_eq!(r.execute("let a=[1,2,3];a.reverse();a.join(\"-\");").unwrap(),Value::String("3-2-1".into()));}#[test]fn additional_string_methods(){let mut r=Runtime::new();assert_eq!(r.execute("\"  hi  \".trim();").unwrap(),Value::String("hi".into()));assert_eq!(r.execute("\"hello\".startsWith(\"he\");").unwrap(),Value::Boolean(true));assert_eq!(r.execute("\"hello\".endsWith(\"lo\");").unwrap(),Value::Boolean(true));}#[test]fn do_while_runs_body_before_condition(){let mut r=Runtime::new();assert_eq!(r.execute("let x=0;do{x=x+1;}while(x<3);x;").unwrap(),Value::Number(3.0));assert_eq!(r.execute("let y=0;do{y=7;}while(false);y;").unwrap(),Value::Number(7.0));}#[test]fn classic_for_loop(){let mut r=Runtime::new();assert_eq!(r.execute("let sum=0;for(let i=0;i<5;i=i+1){sum=sum+i;}sum;").unwrap(),Value::Number(10.0));}#[test]fn for_loop_optional_clauses(){let mut r=Runtime::new();assert_eq!(r.execute("let i=0;for(;i<3;){i=i+1;}i;").unwrap(),Value::Number(3.0));}#[test]fn break_in_for_loop(){let mut r=Runtime::new();assert_eq!(r.execute("let i=0;for(;i<10;i=i+1){if(i===4){break;}}i;").unwrap(),Value::Number(4.0));}#[test]fn continue_in_for_loop_runs_update(){let mut r=Runtime::new();assert_eq!(r.execute("let sum=0;for(let i=0;i<5;i=i+1){if(i===2){continue;}sum=sum+i;}sum;").unwrap(),Value::Number(8.0));}#[test]fn continue_in_while_loop(){let mut r=Runtime::new();assert_eq!(r.execute("let i=0;let sum=0;while(i<4){i=i+1;if(i===2){continue;}sum=sum+i;}sum;").unwrap(),Value::Number(8.0));}#[test]fn break_outside_loop_is_error(){let mut r=Runtime::new();assert!(r.execute("break;").is_err());}#[test]fn continue_outside_loop_is_error(){let mut r=Runtime::new();assert!(r.execute("continue;").is_err());}#[test]fn statements_after_loop_control_are_not_skipped(){let mut r=Runtime::new();assert_eq!(r.execute("let x=0;while(true){x=1;break;x=9;}x;").unwrap(),Value::Number(1.0));}#[test]fn shared_reference(){let mut r=Runtime::new();assert_eq!(r.execute("let a=[1];let b=a;b[0]=8;a[0];").unwrap(),Value::Number(8.0))}}